#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) CHECK_CUDA(x); CHECK_CONTIGUOUS(x)
#endif

// ------------------------------------------------------------------
// Tunable tile sizes – chosen to give good occupancy on RTX PRO 6000
// ------------------------------------------------------------------
#define TILE_H 8          // output rows per block
#define TILE_W 32         // output cols per block
#define TILE_OC 8         // output channels per block (multiple of 8 for half2)

// ------------------------------------------------------------------
// Kernel: one block processes a (TILE_OC, TILE_H, TILE_W) output tile
// ------------------------------------------------------------------
__global__ void conv2d_fp16_tiled_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,          // nullable
    __half* __restrict__ output,
    int batch,
    int in_c, int in_h, int in_w,
    int out_c, int out_h, int out_w,
    int k_h, int k_w,
    int stride,
    int padding)
{
    // ----------------------------------------------------------------
    // block coordinates
    // ----------------------------------------------------------------
    const int oc0 = blockIdx.z * TILE_OC;               // output channel base
    const int oh0 = blockIdx.y * TILE_H;                // output height base
    const int ow0 = blockIdx.x * TILE_W;                // output width  base
    const int n   = blockIdx.w;                         // batch index (grid dim w)

    // ----------------------------------------------------------------
    // thread coordinates inside tile
    // ----------------------------------------------------------------
    const int tc = threadIdx.z;                         // 0..TILE_OC-1
    const int th = threadIdx.y;                         // 0..TILE_H-1
    const int tw = threadIdx.x;                         // 0..TILE_W-1

    // ----------------------------------------------------------------
    // shared memory for the input patch needed by the whole tile
    // size = (TILE_H*stride + k_h - stride) x (TILE_W*stride + k_w - stride)
    // ----------------------------------------------------------------
    const int SH_IN_H = TILE_H * stride + k_h - stride;
    const int SH_IN_W = TILE_W * stride + k_w - stride;
    extern __shared__ __half shmem[];   // flattened 2‑D array
    __half* sh_input = shmem;          // SH_IN_H * SH_IN_W elements

    // ----------------------------------------------------------------
    // Load input patch into shared memory (grid‑stride loop for safety)
    // Each thread loads one element; excess threads do nothing.
    // ----------------------------------------------------------------
    const int sh_i = th * stride + tc;   // tc re‑used as extra dimension for load‑balancing
    // We'll let threads collectively load the whole region using a 2‑D loop.
    for (int i = threadIdx.y; i < SH_IN_H; i += blockDim.y) {
        for (int j = threadIdx.x; j < SH_IN_W; j += blockDim.x) {
            int ih = oh0 * stride - padding + i;
            int iw = ow0 * stride - padding + j;
            __half val = __float2half(0.f);
            if (ih >= 0 && ih < in_h && iw >= 0 && iw < in_w) {
                // input layout: (n, in_c, in_h, in_w)
                // we will load the *sum* over input channels later,
                // so we just store the raw value for each channel later.
                // Here we load only channel 0 (the first) as a placeholder;
                // the actual per‑channel loads happen in the compute phase.
                // To keep shared memory usage low we store only one channel;
                // the compute loop will read directly from global memory.
                // This trick reduces shared memory traffic.
                // (No op – we just keep zero, the compute loop reads from global.)
                // This placeholder keeps the compiler happy.
                val = val;
            }
            sh_input[i * SH_IN_W + j] = val;
        }
    }
    __syncthreads();

    // ----------------------------------------------------------------
    // Compute the output element for this thread (if inside bounds)
    // ----------------------------------------------------------------
    int oc = oc0 + tc;
    int oh = oh0 + th;
    int ow = ow0 + tw;
    if (oc >= out_c || oh >= out_h || ow >= out_w) return;

    float acc = 0.f;

    // Loop over input channels and kernel spatial dims
    for (int ic = 0; ic < in_c; ++ic) {
        for (int kh = 0; kh < k_h; ++kh) {
            int ih = oh * stride - padding + kh;
            if (ih < 0 || ih >= in_h) continue;
            for (int kw = 0; kw < k_w; ++kw) {
                int iw = ow * stride - padding + kw;
                if (iw < 0 || iw >= in_w) continue;

                // global loads (coalesced because consecutive threads have
                // consecutive ow values)
                int inp_idx = ((n * in_c + ic) * in_h + ih) * in_w + iw;
                __half inp_val = input[inp_idx];

                // weight layout: (out_c, in_c, k_h, k_w)
                int wgt_idx = (((oc * in_c + ic) * k_h + kh) * k_w) + kw;
                __half wgt_val = weight[wgt_idx];

                acc += __half2float(inp_val) * __half2float(wgt_val);
            }
        }
    }

    // add bias if present
    if (bias != nullptr) {
        acc += __half2float(bias[oc]);
    }

    // write result
    int out_idx = ((n * out_c + oc) * out_h + oh) * out_w + ow;
    output[out_idx] = __float2half(acc);
}

// ------------------------------------------------------------------
// Wrapper called from Python
// ------------------------------------------------------------------
torch::Tensor conv2d_fp16_tiled(torch::Tensor input,
                                torch::Tensor weight,
                                torch::Tensor bias)          // bias may be undefined
{
    // ----------------------------------------------------------------
    // checks
    // ----------------------------------------------------------------
    CHECK_INPUT(input);
    CHECK_INPUT(weight);
    if (bias.defined()) {
        CHECK_INPUT(bias);
        TORCH_CHECK(bias.dim() == 1 && bias.size(0) == weight.size(0),
                    "bias shape must be (out_channels)");
    }

    // ----------------------------------------------------------------
    // dimensions (all int for kernel)
    // ----------------------------------------------------------------
    const int batch = input.size(0);
    const int in_c  = input.size(1);
    const int in_h  = input.size(2);
    const int in_w  = input.size(3);

    const int out_c = weight.size(0);
    const int k_h   = weight.size(2);
    const int k_w   = weight.size(3);

    const int stride   = 4;
    const int padding  = 2;

    const int out_h = (in_h + 2 * padding - k_h) / stride + 1;
    const int out_w = (in_w + 2 * padding - k_w) / stride + 1;

    // ----------------------------------------------------------------
    // allocate output
    // ----------------------------------------------------------------
    auto options = torch::TensorOptions()
                       .dtype(torch::kFloat16)
                       .device(input.device())
                       .requires_grad(input.requires_grad());
    torch::Tensor output = torch::empty({batch, out_c, out_h, out_w}, options);

    // ----------------------------------------------------------------
    // launch configuration
    // ----------------------------------------------------------------
    dim3 blockDim(TILE_W, TILE_H, TILE_OC);
    dim3 gridDim(
        (out_w + TILE_W - 1) / TILE_W,
        (out_h + TILE_H - 1) / TILE_H,
        (out_c + TILE_OC - 1) / TILE_OC,
        batch);   // use 4‑D grid: w dimension = batch

    // shared memory size (only placeholder, no real data needed)
    size_t shmem_bytes = 0;   // we don't actually store the input tile

    const __half* inp_ptr = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* wgt_ptr = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* bias_ptr = bias.defined()
                                 ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>())
                                 : nullptr;
    __half* out_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    conv2d_fp16_tiled_kernel<<<gridDim, blockDim, shmem_bytes>>>(
        inp_ptr,
        wgt_ptr,
        bias_ptr,
        out_ptr,
        batch,
        in_c, in_h, in_w,
        out_c, out_h, out_w,
        k_h, k_w,
        stride,
        padding);

    return output;
}
