    def __init__(self, num_classes=1000):
        super().__init__()
        # initialise weight/bias exactly like nn.Conv2d
        ref = nn.Conv2d(
            in_channels=3,
            out_channels=96,
            kernel_size=11,
            stride=4,
            padding=2,
