        self.bias   = nn.Parameter(ref.bias.clone())
        self._conv = conv2d_ext.conv2d_fp16_tiled

    def forward(self, x):
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        x = x.to(torch.float16).contiguous()
        w = self.weight.contiguous()
        b = self.bias.contiguous()
        return self._conv(x, w, b)
